89	func scheduleFuzzer(f *fuzz.Fuzzer) *fuzz.Fuzzer {
90		return f.Funcs(
91			func(t *time.Time, c fuzz.Continue) {
92				if c.Intn(10) < 3 {
93					*t = time.Time{}
94					return
95				}
96				*t = time.Unix(c.Int63n(4102444800), c.Int63n(1e9)).UTC()
97			},
98			func(d *time.Duration, c fuzz.Continue) {
99				if c.Intn(10) < 3 {
100					*d = 0
101					return
102				}
103				*d = time.Duration(c.Int63n(int64(24 * time.Hour)))
104			},
105			func(p *types.ScheduleOverlapPolicy, c fuzz.Continue) {
106				*p = types.ScheduleOverlapPolicy(c.Intn(6)) // 0-5: Invalid through TerminatePrevious
107			},
108			func(p *types.ScheduleCatchUpPolicy, c fuzz.Continue) {
109				*p = types.ScheduleCatchUpPolicy(c.Intn(4)) // 0-3: Invalid through All
110			},
111			func(p *types.TaskListKind, c fuzz.Continue) {
112				*p = types.TaskListKind(c.Intn(3)) // 0-2: Normal, Sticky, Ephemeral
113			},
114		).NilChance(0.3)
115	}
